            "question": "Create following tables with primary and foreign keys and solve the queries given below. Primary keys are underlined\nPerson (driver_id, name, address)\nCar (license, model, year)\nAccident (report_no, date_acc, location)\nOwns (driver_id, license)\nParticipated (driver_id, model, report_no, damage_amount)\n1) Insert 5 records into each table\n2) Display the Schema of each table.\n3) Display all records from the person table\n4) Set a Foreign key constraint from Participated.report_no to Accident.report_no.\n5) Add check constraints on Damage_amount that amt should not be negative.\n6) Write a query to make the name column in the Person table NOT NULL.\n7) Rename the Car table to Vehicle.\n8) Create a new table named new_person from existing person table and drop the table new_person.",
            "solution": "CREATE TABLE Person(\ndriver_id NUMBER PRIMARY KEY,\nname VARCHAR2(50),\naddress VARCHAR2(100)\n);\n\nCREATE TABLE Car(\nlicense VARCHAR2(20) PRIMARY KEY,\nmodel VARCHAR2(30),\nyear NUMBER(4)\n);\n\nCREATE TABLE Accident(\nreport_no NUMBER PRIMARY KEY,\ndate_acc DATE,\nlocation VARCHAR2(100)\n);\n\nCREATE TABLE Owns(\ndriver_id NUMBER,\nlicense VARCHAR2(20),\nPRIMARY KEY(driver_id,license),\nFOREIGN KEY(driver_id) REFERENCES Person(driver_id),\nFOREIGN KEY(license) REFERENCES Car(license)\n);\n\nCREATE TABLE Participated(\ndriver_id NUMBER,\nmodel VARCHAR2(30),\nreport_no NUMBER,\ndamage_amount NUMBER,\nPRIMARY KEY(driver_id,report_no)\n);\n\nINSERT INTO Person VALUES(1,'Amit','Pune');\nINSERT INTO Person VALUES(2,'Rohit','Mumbai');\nINSERT INTO Person VALUES(3,'Sneha','Nashik');\nINSERT INTO Person VALUES(4,'Priya','Nagpur');\nINSERT INTO Person VALUES(5,'Karan','Delhi');\n\nINSERT INTO Car VALUES('MH12AB1234','Honda',2020);\nINSERT INTO Car VALUES('MH14XY5678','Hyundai',2021);\nINSERT INTO Car VALUES('MH01CD3456','Toyota',2019);\nINSERT INTO Car VALUES('MH20EF7890','BMW',2022);\nINSERT INTO Car VALUES('MH15GH4321','Audi',2023);\n\nINSERT INTO Accident VALUES(101,TO_DATE('10-01-2025','DD-MM-YYYY'),'Pune');\nINSERT INTO Accident VALUES(102,TO_DATE('15-02-2025','DD-MM-YYYY'),'Mumbai');\nINSERT INTO Accident VALUES(103,TO_DATE('20-03-2025','DD-MM-YYYY'),'Nashik');\nINSERT INTO Accident VALUES(104,TO_DATE('25-04-2025','DD-MM-YYYY'),'Delhi');\nINSERT INTO Accident VALUES(105,TO_DATE('30-05-2025','DD-MM-YYYY'),'Nagpur');\n\nINSERT INTO Owns VALUES(1,'MH12AB1234');\nINSERT INTO Owns VALUES(2,'MH14XY5678');\nINSERT INTO Owns VALUES(3,'MH01CD3456');\nINSERT INTO Owns VALUES(4,'MH20EF7890');\nINSERT INTO Owns VALUES(5,'MH15GH4321');\n\nINSERT INTO Participated VALUES(1,'Honda',101,20000);\nINSERT INTO Participated VALUES(2,'Hyundai',102,15000);\nINSERT INTO Participated VALUES(3,'Toyota',103,10000);\nINSERT INTO Participated VALUES(4,'BMW',104,50000);\nINSERT INTO Participated VALUES(5,'Audi',105,30000);\n\nDESC Person;\nDESC Car;\nDESC Accident;\nDESC Owns;\nDESC Participated;\n\nSELECT * FROM Person;\n\nALTER TABLE Participated\nADD CONSTRAINT fk_report\nFOREIGN KEY(report_no)\nREFERENCES Accident(report_no);\n\nALTER TABLE Participated\nADD CONSTRAINT chk_damage\nCHECK(damage_amount >= 0);\n\nALTER TABLE Person\nMODIFY name VARCHAR2(50) NOT NULL;\n\nRENAME Car TO Vehicle;\n\nCREATE TABLE new_person AS\nSELECT * FROM Person;\n\nSELECT * FROM new_person;\n\nDROP TABLE new_person;"
