            "solution": "CREATE TABLE Department(\ndept_id NUMBER PRIMARY KEY,\ndept_name VARCHAR2(30),\nlocation VARCHAR2(30)\n);\n\nCREATE TABLE Employee(\nemp_id NUMBER PRIMARY KEY,\nemp_name VARCHAR2(30),\ncity VARCHAR2(30),\nsalary NUMBER,\ndepartment NUMBER,\nFOREIGN KEY(department) REFERENCES Department(dept_id)\n);\n\nINSERT INTO Department VALUES(1,'IT','Pune');\nINSERT INTO Department VALUES(2,'HR','Mumbai');\nINSERT INTO Department VALUES(3,'Sales','Delhi');\nINSERT INTO Department VALUES(4,'Finance','Chennai');\nINSERT INTO Department VALUES(5,'Admin','Nagpur');\n\nINSERT INTO Employee VALUES(101,'Amit','Mumbai',50000,1);\nINSERT INTO Employee VALUES(102,'Rohit','Pune',60000,1);\nINSERT INTO Employee VALUES(103,'Sneha','Delhi',45000,2);\nINSERT INTO Employee VALUES(104,'Karan','Nagpur',70000,3);\nINSERT INTO Employee VALUES(105,'Priya','Mumbai',80000,4);\nINSERT INTO Employee VALUES(106,'Neha','Pune',55000,5);\nINSERT INTO Employee VALUES(107,'Ajay','Delhi',40000,2);\nINSERT INTO Employee VALUES(108,'Tejas','Mumbai',75000,1);\nINSERT INTO Employee VALUES(109,'Seema','Nagpur',65000,3);\nINSERT INTO Employee VALUES(110,'Komal','Pune',72000,4);\n\nDESC Employee;\nDESC Department;\n\nSELECT * FROM Employee;\nSELECT * FROM Department;\n\nINSERT INTO Department\nVALUES(6,'Testing','Hyderabad');\n\nINSERT INTO Employee(emp_id,emp_name,city,department)\nVALUES(111,'Raj','Pune',1);\n\nUPDATE Employee\nSET salary=salary+(salary*0.20);\n\nSELECT emp_name,salary*12 AS annual_salary\nFROM Employee\nWHERE emp_name LIKE '_e%';\n\nUPDATE Employee\nSET city='Pune'\nWHERE department=(\nSELECT dept_id\nFROM Department\nWHERE dept_name='IT'\n);"
