            "solution": "CREATE TABLE Department1(\ndept_id NUMBER PRIMARY KEY,\ndept_name VARCHAR2(30),\nlocation VARCHAR2(30)\n);\n\nCREATE TABLE Employee1(\nemp_id NUMBER PRIMARY KEY,\nemp_name VARCHAR2(30),\ncity VARCHAR2(30),\nsalary NUMBER,\ndepartment NUMBER,\nFOREIGN KEY(department) REFERENCES Department1(dept_id)\n);\n\nINSERT INTO Department1 VALUES(1,'IT','Pune');\nINSERT INTO Department1 VALUES(2,'HR','Mumbai');\nINSERT INTO Department1 VALUES(3,'Sales','Delhi');\nINSERT INTO Department1 VALUES(4,'Finance','Chennai');\nINSERT INTO Department1 VALUES(5,'Admin','Nagpur');\n\nINSERT INTO Employee1 VALUES(101,'Amit','Mumbai',50000,1);\nINSERT INTO Employee1 VALUES(102,'Rohit','Pune',60000,1);\nINSERT INTO Employee1 VALUES(103,'Sneha','Delhi',45000,2);\nINSERT INTO Employee1 VALUES(104,'Karan','Nagpur',120000,3);\nINSERT INTO Employee1 VALUES(105,'Priya','Mumbai',80000,4);\nINSERT INTO Employee1 VALUES(106,'Neha','Pune',55000,5);\nINSERT INTO Employee1 VALUES(107,'Ajay','Delhi',40000,2);\nINSERT INTO Employee1 VALUES(108,'Tejas','Mumbai',75000,1);\nINSERT INTO Employee1 VALUES(109,'Seema','Nagpur',65000,3);\nINSERT INTO Employee1 VALUES(110,'Komal','Pune',72000,4);\n\nDESC Employee1;\nDESC Department1;\n\nUPDATE Employee1\nSET city='Pune'\nWHERE department=(\nSELECT dept_id\nFROM Department1\nWHERE dept_name='IT'\n);\n\nDELETE FROM Employee1\nWHERE salary>100000;\n\nSELECT emp_name,salary-(salary*0.05) AS salary_after_tax\nFROM Employee1;\n\nSELECT *\nFROM Employee1\nWHERE city<>'Mumbai'\nAND emp_name LIKE 'A%';\n\nSELECT *\nFROM Employee1\nWHERE department=(\nSELECT dept_id\nFROM Department1\nWHERE dept_name='IT'\n)\nAND salary>50000;"
