            "solution": "CREATE TABLE Employee4(\nemp_id NUMBER PRIMARY KEY,\nemp_name VARCHAR2(30),\ndepartment VARCHAR2(30),\ncity VARCHAR2(30),\nsalary NUMBER\n);\n\nINSERT INTO Employee4 VALUES(101,'Amit','IT','Pune',50000);\nINSERT INTO Employee4 VALUES(102,'Rohit','IT','Mumbai',60000);\nINSERT INTO Employee4 VALUES(103,'Sneha','HR','Pune',45000);\nINSERT INTO Employee4 VALUES(104,'Karan','Sales','Delhi',70000);\nINSERT INTO Employee4 VALUES(105,'Priya','Finance','Mumbai',80000);\nINSERT INTO Employee4 VALUES(106,'Neha','IT','Pune',55000);\nINSERT INTO Employee4 VALUES(107,'Ajay','HR','Delhi',40000);\nINSERT INTO Employee4 VALUES(108,'Tejas','IT','Mumbai',75000);\nINSERT INTO Employee4 VALUES(109,'Seema','Sales','Nagpur',65000);\nINSERT INTO Employee4 VALUES(110,'Komal','Finance','Pune',72000);\n\nSELECT department,SUM(salary) AS Total_Salary\nFROM Employee4\nGROUP BY department\nHAVING SUM(salary)>200000;\n\nSELECT department,AVG(salary) AS Average_Salary\nFROM Employee4\nGROUP BY department\nHAVING AVG(salary)>40000;\n\nSELECT city,COUNT(*) AS Number_Of_Employees\nFROM Employee4\nGROUP BY city;\n\nSELECT department,MAX(salary) AS Maximum_Salary\nFROM Employee4\nGROUP BY department;\n\nSELECT city,AVG(salary) AS Average_Salary\nFROM Employee4\nGROUP BY city;\n\nSELECT department,COUNT(*) AS Employee_Count\nFROM Employee4\nGROUP BY department\nHAVING COUNT(*)>3;\n\nSELECT city,COUNT(*) AS Employee_Count\nFROM Employee4\nGROUP BY city\nORDER BY COUNT(*) ASC;"
