            "question": "PL/SQL Stored Procedure.\nWrite a Stored Procedure namely proc_Grade for the categorization of student. If marks scored by students in examination is <=1500 and marks>=990 then student will be placed in distinction category if marks scored are between 989 and900 category is first class, if marks 899 and 825 category is Higher Second Class\nWrite a PL/SQL block for using procedure created with above requirement. Stud_Marks(name, total_marks) Result(Roll,Name, Class).",
            "solution": "CREATE TABLE Stud_Marks(\nroll NUMBER,\nname VARCHAR2(30),\ntotal_marks NUMBER\n);\n\nCREATE TABLE Result(\nroll NUMBER,\nname VARCHAR2(30),\nclass VARCHAR2(30)\n);\n\nINSERT INTO Stud_Marks VALUES(1,'Amit',1200);\nINSERT INTO Stud_Marks VALUES(2,'Rohit',950);\nINSERT INTO Stud_Marks VALUES(3,'Sneha',850);\n\nCREATE OR REPLACE PROCEDURE proc_grade(\np_roll NUMBER,\np_name VARCHAR2,\np_marks NUMBER\n)\nIS\nv_class VARCHAR2(30);\nBEGIN\n\nIF p_marks<=1500 AND p_marks>=990 THEN\nv_class:='Distinction';\n\nELSIF p_marks BETWEEN 900 AND 989 THEN\nv_class:='First Class';\n\nELSIF p_marks BETWEEN 825 AND 899 THEN\nv_class:='Higher Second Class';\n\nELSE\nv_class:='Fail';\nEND IF;\n\nINSERT INTO Result\nVALUES(p_roll,p_name,v_class);\n\nEND;\n/\n\nBEGIN\nproc_grade(1,'Amit',1200);\nproc_grade(2,'Rohit',950);\nproc_grade(3,'Sneha',850);\nEND;\n/\n\nSELECT * FROM Result;"
